local UIActivitySkinShopCellNode = Class('UIActivitySkinShopCellNode')

function UIActivitySkinShopCellNode:__init()
    self._data = nil
    self.handler = nil
end

function UIActivitySkinShopCellNode:__delete()
    self._data = nil
    self.handler = nil
end

function UIActivitySkinShopCellNode:Awake()
    SetButtonAction(self.BtnNode, Bind(self, self.OnClick))
    self.handler = Events.AddListener("SKIN_SHOP_TIME_COUNT_DOWN", function()
        if self._data and not isNull(self._data.endTime) then
            self:RefreshData(self._data)
        end
    end)
end

function UIActivitySkinShopCellNode:Refresh(data, cb)
    if not data then
        return
    end
    self._data = data
    self._cb = cb
    self:FillSelf()
end

function UIActivitySkinShopCellNode:RefreshData(data)
    if not data then
        return
    end
    self._data = data
    self:FillSelf()
end

function UIActivitySkinShopCellNode:FillSelf()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data.icon)
    if not vo then return end

    -- icon
    CfUtils.FillImage(self.ImgIcon, vo.photoPath)
    CfUtils.SetUISwitchImage(self.GoodQuality, vo.quality)
    CfUtils.SetUISwitchImage(self.GoodQuality2, vo.quality)
    CfUtils.SetActive(self.BtnNode.transform:Find("TimerGroup"), false)

    -- name
    CfUtils.FillText(self.TextName, tostring(vo.name) .. "x" ..self._data.num)

    -- 库存
    if checkNumber(self._data.stock) == -1 then
        CfUtils.SetActive(self.Stock, false)
    else
        CfUtils.SetActive(self.Stock, true)
        CfUtils.FillText(self.TextNumber, self._data.currentStock)
    end
    local keys = table.keys(self._data.prices)
    CfUtils.SetActive(self.ImgIcon2, true)
    CfUtils.FillImage(self.ImgIcon2, GoodsConfMgr:GetInstance():GetPhotoPathById(keys[1]))
    CfUtils.FillText(self.TextNumber3, self._data.prices[keys[1]].current)
    if checkNumber(self._data.prices[keys[1]].original) > 0 then
        local PriceTrans = self.PriceObject.transform:Find("Price1/Price2")
        CfUtils.SetActive(PriceTrans, true)
        if PriceTrans then
            CfUtils.FillImage(PriceTrans:Find("TextNumber/ImgIcon"), GoodsConfMgr:GetInstance():GetPhotoPathById(keys[1]))
            CfUtils.FillText(PriceTrans:Find("TextNumber"), self._data.prices[keys[1]].original)
        end
    else
        CfUtils.SetActive(self.PriceObject.transform:Find("Price1/Price2"), false)
    end

    -- 星级
    for i = 1, self.Star.childCount do
        local go = self.Star:Find('ImgStar'..i)
        if isNotNull(go) then
            CfUtils.SetActive(go, checkInt(vo.quality) >= i)
        end
    end

    -- 标签
    local tabType = checkInt(self._data.iconId)
    if tabType == TagType.Activity then
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityTabelGroup, false)
        CfUtils.SetActive(self.DiscountGroup.transform.parent:Find("TimeLimitGroup"), true)
        CfUtils.FillText(self.DiscountGroup.transform.parent:Find("TimeLimitGroup/TxtTimeLimit"), localize('限时'))
    elseif tabType == TagType.Discount then
        CfUtils.FillText(self.TxtDiscount, localize('折扣'))
        CfUtils.SetActive(self.TxtDiscount, true)
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.TxtNumber5, false)
        CfUtils.SetActive(self.ActivityTabelGroup, false)
        CfUtils.SetActive(self.DiscountGroup.transform.parent:Find("TimeLimitGroup"), false)
    else
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityTabelGroup, false)
        CfUtils.SetActive(self.DiscountGroup.transform.parent:Find("TimeLimitGroup"), false)
    end
    
    --特殊类型处理
    local goodsType = GoodsUtils.GetIdType(self._data.icon)
    if goodsType == Constants.IDType.Equipment then
        CfUtils.SetActive(self.EquipGroup, false)
        CfUtils.SetActive(self.ImgIcon, true)
        CfUtils.SetActive(self.RoleGoods, false)
        CfUtils.SetActive(self.PokerCardRoot, false)
    elseif goodsType == Constants.IDType.CardSkin or goodsType == Constants.IDType.CharacterCard then
        CfUtils.SetActive(self.EquipGroup, false)
        CfUtils.SetActive(self.ImgIcon, false)
        CfUtils.SetActive(self.RoleGoods, true)
        CfUtils.SetActive(self.ImgOccupation, goodsType == Constants.IDType.CardSkin)
        CfUtils.FillImage(self.ImgRoleIcon, vo.photoPath)
        CfUtils.SetActive(self.PokerCardRoot, false)
    elseif goodsType == Constants.IDType.BattleCardGameCard then
        CfUtils.SetActive(self.EquipGroup, false)
        CfUtils.SetActive(self.ImgIcon, false)
        CfUtils.SetActive(self.RoleGoods, false)
        CfUtils.SetActive(self.PokerCardRoot, true)
        self:RefreshBattleCardNode_()
    else
        CfUtils.SetActive(self.EquipGroup, false)
        CfUtils.SetActive(self.RoleGoods, false)
        CfUtils.SetActive(self.ImgIcon, true)
        CfUtils.SetActive(self.PokerCardRoot, false)
    end

    -- local isLocked = not ActivityPtUtils.IsPassQuest(self._data.unlockStory)  --GroceryUtils.ProductIsLocked(self._data)
    local isSoldOut = GroceryUtils.ProductIsSoldOut(self._data)
    -- CfUtils.SetActive(self.DisableBg, isSoldOut or isLocked)
    CfUtils.SetActive(self.DisableBg, isSoldOut)
    -- CfUtils.SetActive(self.LockGroup, isLocked)
    CfUtils.SetActive(self.SellOutGroup, isSoldOut)
    CfUtils.SetActive(self.HadGroup, false)
    if not isSoldOut then
        local isOnly = GroceryUtils.ProductIsOnly(self._data)
        CfUtils.SetActive(self.DisableBg, isOnly)
        CfUtils.SetActive(self.HadGroup, isOnly)
        if not isOnly then
            ---未拥有的情况下
            CfUtils.SetActive(self.TextTime.transform.parent, checkNumber(self._data.endTime) > 0)
            if checkNumber(self._data.endTime) > 0 then
                ---存在倒计时
                CfUtils.FillText(self.TextTime,  CfUtils.GetTimeHMS(self._data.endTime))
            end
        end
    end

    -- CfUtils.SetActive(self.Text2, isLocked)
    -- if isLocked then
    --     local vo = ActivityPtUtils.GetActivityPtPlotVo(self._data.unlockStory)
    --     CfUtils.FillText(self.Text2, vo.name)
    -- else
    -- end
end


function UIActivitySkinShopCellNode:RefreshBattleCardNode_()
    local battleCardId = checkInt(self._data.icon)
    if isNull(self.pokerCardNode_) then
        self.pokerCardNode_ = BattleCardGameUtils.LoadBattleCardNode(self.PokerCardRoot)
    end
    BattleCardGameUtils.UpcateBattleCardNode(self.pokerCardNode_, battleCardId)
end


